-- Canonical publication identities and original Thomas-authored abstracts.
-- @statement
    document_id, authority_id, canonical_title, publisher, publication_family,
    canonical_identifier, thomas_relevance_abstract, non_authorization_statement
) VALUES
('who-unicef-foundational-helping', 'WHO_UNICEF', 'Foundational helping skills training manual: a competency-based approach for training helpers to support adults', 'World Health Organization and United Nations Children''s Fund', 'EQUIP', 'ISBN 978-92-4-010593-5', 'A competency-based training manual for trainers and supervisors preparing helpers who support adults. Its observable helping-skill focus may later inform Thomas source analysis and qualification design.', 'The record does not adopt the manual''s 15 competencies as Thomas concepts, certify Thomas as a helper, or authorize autonomous therapeutic behavior.'),
('who-unicef-equip-compendium', 'WHO_UNICEF', 'Ensuring Quality in Psychosocial and Mental Health Care (EQUIP): compendium of competency assessment tools', 'World Health Organization and United Nations Children''s Fund', 'EQUIP', 'ISBN 978-92-4-012104-1', 'A compendium describing the EQUIP competency assessment tools, their evidence base, and practical application. It may later support layer-specific and observable performance qualification.', 'The record neither implements an EQUIP tool nor claims that a software system can be assessed as if it were a trained human helper.'),
('who-pm-plus-individual', 'WHO', 'Problem management plus (PM+): individual psychological help for adults impaired by distress in communities exposed to adversity', 'World Health Organization', 'Problem Management Plus', 'WHO/MSD/MER/18.5', 'The generic field-trial intervention manual documents a bounded, scalable intervention for adults experiencing distress in adversity-affected communities. It is retained as a procedural source candidate with its delivery assumptions intact.', 'The record does not encode PM+ stages, authorize unsupervised delivery, or establish fit for Thomas''s intended population or product setting.'),
('who-pm-plus-training', 'WHO', 'Problem Management Plus (PM+) psychological intervention for individuals: training manual', 'World Health Organization', 'Problem Management Plus', 'ISBN 978-92-4-010992-6', 'The current training manual describes preparation, supervision, implementation, and competency assessment for people or organizations training PM+ helpers. It is linked to, but not substituted for, the intervention manual.', 'The record grants neither competence nor implementation authority and does not turn training instructions into runtime behavior.'),
('who-psychological-self-help', 'WHO', 'Psychological self-help interventions: delivering self-help for individuals, featuring Step-by-Step and Doing What Matters in Times of Stress', 'World Health Organization', 'Psychological self-help interventions', 'ISBN 978-92-4-012078-5', 'A delivery manual covering WHO psychological self-help interventions, including Step-by-Step and Doing What Matters in Times of Stress. Its mobile and self-help context makes it a high-value source candidate for later scope analysis.', 'The record does not copy an exercise or script, approve autonomous delivery, or conclude that a mobile product is an equivalent delivery setting.'),
('who-step-by-step-annex', 'WHO', 'Step-by-Step intervention material', 'World Health Organization', 'Psychological self-help interventions', 'WHO reference B09738', 'An official web annex containing intervention material associated with the 2026 psychological self-help delivery manual. It is separately addressable so the annex cannot be mistaken for the higher-level manual.', 'The record does not reproduce or implement the intervention material and does not grant commercial adaptation rights.'),
('who-psychological-implementation', 'WHO', 'Psychological interventions implementation manual: integrating evidence-based psychological interventions into existing services', 'World Health Organization', 'Psychological interventions implementation', 'ISBN 978-92-4-008714-9', 'An implementation manual for managers and service planners covering planning, contextual adaptation, workforce preparation, beneficiary support, monitoring, and evaluation of manualized interventions.', 'The record is implementation/process evidence, not a direct therapeutic procedure, clinical recommendation, or authorization for software delivery.'),
('who-mhgap-guideline', 'WHO', 'Mental Health Gap Action Programme (mhGAP) guideline for mental, neurological and substance use disorders', 'World Health Organization', 'mhGAP guidelines', 'ISBN 978-92-4-008427-8', 'The mhGAP guideline family supplies current WHO evidence recommendations for non-specialist health workers and records the prior 2015 update as superseded history. Versions remain separate so current recommendations cannot be silently replaced by older material.', 'The record does not diagnose, prescribe, create a clinical algorithm, or establish that Thomas is a non-specialist health worker.'),
('who-mhgap-intervention-guide', 'WHO', 'mhGAP Intervention Guide for mental, neurological and substance use disorders in non-specialized health settings', 'World Health Organization', 'mhGAP Intervention Guide', 'ISBN 978-92-4-154979-0', 'The intervention-guide family presents explicit integrated-management procedures for trained health workers in non-specialized health settings. Both versions are retained so version 2.0 can be distinguished from its 2010 predecessor and from the newer evidence guideline.', 'The record does not authorize use of a clinical decision algorithm by unsupervised software; newer guideline recommendations must later be adjudicated before any procedural reliance.'),
('who-live-life', 'WHO', 'LIVE LIFE: an implementation guide for suicide prevention in countries', 'World Health Organization', 'LIVE LIFE', 'ISBN 978-92-4-002662-9', 'A public-health implementation guide for national and local suicide-prevention activity involving governments, focal points, and community stakeholders. It broadens the safety corpus beyond individual screening tools.', 'The record is not an individual crisis algorithm, does not establish product emergency behavior, and does not authorize Thomas to perform clinical risk assessment.'),
('nice-ng222', 'NICE', 'Depression in adults: treatment and management', 'National Institute for Health and Care Excellence', 'NICE guideline', 'NG222', 'A current NICE guideline for identifying, treating, and managing depression in adults, with a January 2026 surveillance decision retaining its recommendations. It is a high-authority source candidate within its jurisdiction and scope.', 'The record does not diagnose depression, choose treatment, reproduce recommendation text for product use, or extend NICE authority beyond the guideline population and setting.'),
('nice-ng225', 'NICE', 'Self-harm: assessment, management and preventing recurrence', 'National Institute for Health and Care Excellence', 'NICE guideline', 'NG225', 'A current cross-sector NICE guideline for children, young people, and adults after self-harm. Its numbered recommendation structure supports precise citation of both positive and negative guidance.', 'The record does not implement self-harm logic, a risk score, stratification, clinical assessment, or referral behavior; international and AI reuse remain permission-gated.'),
('nimh-asq-toolkit', 'NIMH', 'Ask Suicide-Screening Questions (ASQ) Toolkit', 'National Institute of Mental Health', 'ASQ', 'NIMH ASQ Toolkit', 'An official collection of screening tools and setting-specific clinical pathways for medical settings, with distinct youth and adult material. It records that positive screens lead to assessment by a trained clinician.', 'A screening toolkit is not a Thomas decision algorithm, and its pathways do not establish safety for unsupervised software or non-medical settings.'),
('nimh-asq-screening-tool', 'NIMH', 'Ask Suicide-Screening Questions (ASQ) Suicide Risk Screening Tool', 'National Institute of Mental Health', 'ASQ', 'NIMH Toolkit: Screening Tool for Youth and Adults', 'A one-page NIMH screening instrument for youth and adult medical patients, captured separately from the surrounding toolkit and pathways.', 'The record does not implement, score, ask, or route on the instrument and does not establish authority to deploy it outside its validated setting.'),
('va-safety-planning', 'VA', 'Safety Planning', 'United States Department of Veterans Affairs', 'Evidence-Based Treatment', 'VA EBT Safety Planning', 'An official VA description of collaborative safety planning with a provider for Veterans experiencing suicidal thoughts or behaviors. It is included as a public-sector safety-planning source candidate.', 'The record does not reproduce a safety plan, assume Thomas can act as the provider, or establish rights to third-party safety-planning intellectual property.'),
('samhsa-tip35', 'SAMHSA', 'Enhancing Motivation for Change in Substance Use Disorder Treatment', 'Substance Abuse and Mental Health Services Administration', 'Treatment Improvement Protocol', 'TIP 35 / PEP19-02-01-003', 'A government treatment-improvement protocol updated in 2019 for clinicians incorporating motivational interventions into substance-use treatment. It may later supplement primary Motivational Interviewing bibliography with public-sector procedural context.', 'The record does not generalize substance-use treatment guidance to all users, reproduce third-party copyrighted content, or implement motivational dialogue behavior.'),
('cci-self-help-collection', 'CCI', 'Looking After Yourself: self-help resources for mental health problems', 'State of Western Australia, North Metropolitan Health Service', 'CCI self-help resources', 'CCI Looking After Yourself', 'A structured collection of cognitive-behavioral self-help workbooks, information sheets, and worksheets spanning several common problem domains. Domain pages are recorded as addressable sections rather than copied artifacts.', 'The record does not presume clinical equivalence, redistribution, commercial adaptation, diagnosis, or use as a substitute for qualified care.'),
('nist-ai-rmf', 'NIST', 'Artificial Intelligence Risk Management Framework (AI RMF 1.0)', 'National Institute of Standards and Technology', 'NIST AI publications', 'NIST AI 100-1 / DOI 10.6028/NIST.AI.100-1', 'A voluntary, non-sector-specific engineering framework for managing risks across the AI lifecycle. It proves that engineering governance can share provenance infrastructure without being confused with clinical authority.', 'The record supplies no clinical evidence, therapeutic competence, product certification, or claim that following the framework makes Thomas safe.'),
('nist-genai-profile', 'NIST', 'Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile', 'National Institute of Standards and Technology', 'NIST AI publications', 'NIST AI 600-1 / DOI 10.6028/NIST.AI.600-1', 'A cross-sector companion profile identifying risks specific to or amplified by generative AI and suggested risk-management actions. It may later inform renderer and evaluation governance.', 'The record supplies no clinical authority, does not approve any model, and does not alter Thomas''s renderer-subordination invariant.');
-- @statement
